63	          {mb.comprovante_endereco_url && (
64	            <a href={mb.comprovante_endereco_url} target="_blank" rel="noreferrer"
65	              className="flex items-center gap-2 border border-gray-200 dark:border-gray-800 rounded-xl px-3 py-2.5 text-sm text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40">
66	              <Icon name="FileText" size={16} /> Ver comprovante de endereço
67	            </a>
68	          )}
69	        </div>
70	
71	        {somenteLeitura ? (
72	          <button onClick={onFechar} className="w-full mt-5 py-2.5 border rounded-xl text-sm text-gray-700 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-950/40">
73	            Fechar
74	          </button>
75	        ) : mostrarRecusa ? (
76	          <div className="mt-5 space-y-2">
77	            <textarea value={motivo} onChange={(e) => setMotivo(e.target.value)} rows={3}
78	              placeholder="Motivo da recusa (opcional)"
79	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-red-400 resize-none" />
80	            <div className="flex gap-2">
81	              <button onClick={() => setMostrarRecusa(false)} className="flex-1 py-2.5 border rounded-xl text-sm text-gray-700 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-950/40">
82	                Voltar
83	              </button>
84	              <button onClick={() => onRecusar(solicitacao.id, motivo)} disabled={processando}
85	                className="flex-1 py-2.5 bg-red-600 text-white rounded-xl text-sm font-semibold hover:bg-red-700 disabled:opacity-50">
86	                Confirmar recusa
87	              </button>
88	            </div>
89	          </div>
90	        ) : (
91	          <div className="flex gap-2 mt-5">
92	            <button onClick={() => setMostrarRecusa(true)} disabled={processando}
93	              className="flex-1 py-2.5 border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 rounded-xl text-sm font-semibold hover:bg-red-50 dark:hover:bg-red-950/40 disabled:opacity-50">
94	              Recusar
95	            </button>
96	            <button onClick={() => onAceitar(solicitacao.id)} disabled={processando}
97	              className="flex-1 py-2.5 bg-green-600 text-white rounded-xl text-sm font-semibold hover:bg-green-700 disabled:opacity-50">
98	              {processando ? 'Aguarde...' : 'Aceitar'}
99	            </button>
100	          </div>
101	        )}
102	      </div>
103	    </div>
104	  );
105	};
106	
107	const RestauranteMotoboys = () => {
108	  const [aba, setAba] = useState('pendentes'); // pendentes | aceitas | recusadas
109	  const [motoboys, setMotoboys] = useState([]);
110	  const [solicitacoes, setSolicitacoes] = useState([]);
111	  const [recusadas, setRecusadas] = useState([]);
112	  const [loading, setLoading] = useState(true);
113	  const [msg, setMsg] = useState(null);
114	  const [ficha, setFicha] = useState(null); // solicitacao selecionada
115	  const [fichaSomenteLeitura, setFichaSomenteLeitura] = useState(false);
116	  const [processando, setProcessando] = useState(false);
117	  const [removendo, setRemovendo] = useState(null);
118	  const [revisando, setRevisando] = useState(null);
119	  const [forcandoLogout, setForcandoLogout] = useState(null);
120	
121	  const reload = useCallback(() => {
122	    setLoading(true);
123	    Promise.all([listarMotoboys(), listarSolicitacoesMotoboy('pendente'), listarSolicitacoesMotoboy('recusado')])
124	      .then(([mbs, sols, recs]) => {
125	        setMotoboys(mbs.motoboys ?? []);
126	        setSolicitacoes(sols.solicitacoes ?? []);
127	        setRecusadas(recs.solicitacoes ?? []);
128	      })
129	      .catch((e) => setMsg({ tipo: 'erro', texto: e.message }))
130	      .finally(() => setLoading(false));
131	  }, []);
132	
133	  useEffect(() => { reload(); }, [reload]);
134	
135	  const handleAceitar = async (id) => {
136	    setProcessando(true);
137	    try {
138	      await aceitarSolicitacaoMotoboy(id);
139	      setFicha(null);
140	      setMsg({ tipo: 'ok', texto: 'Motoboy aceito!' });
141	      setTimeout(() => setMsg(null), 3000);
142	      reload();
143	    } catch (err) {
144	      setMsg({ tipo: 'erro', texto: err.message });
145	    } finally {
146	      setProcessando(false);
147	    }
148	  };
149	
150	  const handleRecusar = async (id, motivo) => {
151	    setProcessando(true);
152	    try {
153	      await recusarSolicitacaoMotoboy(id, motivo);
154	      setFicha(null);
155	      reload();
156	    } catch (err) {
157	      setMsg({ tipo: 'erro', texto: err.message });
158	    } finally {
159	      setProcessando(false);
160	    }
161	  };
162	
163	  const handleRevisar = async (id) => {
164	    setRevisando(id);
165	    try {
166	      await revisarSolicitacaoMotoboy(id);
167	      reload();
168	    } catch (err) {
169	      setMsg({ tipo: 'erro', texto: err.message });
170	    } finally {
171	      setRevisando(null);
172	    }
173	  };
174	
175	  const handleForcarLogout = async (mb) => {
176	    if (!window.confirm(`Encerrar a sessão de ${mb.name} no dispositivo onde está logado, pra liberar login em outro?`)) return;
177	    setForcandoLogout(mb.id);
178	    try {
179	      await forcarLogoutMotoboy(mb.id);
180	      setMotoboys((prev) => prev.map((m) => (m.id === mb.id ? { ...m, sessao_ativa: false } : m)));
181	    } catch (err) {
182	      setMsg({ tipo: 'erro', texto: err.message });
183	    } finally {
184	      setForcandoLogout(null);
185	    }
186	  };
187	
188	  const handleRemover = async (mb) => {
189	    if (!window.confirm(`Remover "${mb.name}" dos seus entregadores?`)) return;
190	    setRemovendo(mb.id);
191	    try {
192	      await removerAfiliacaoMotoboy(mb.id);
193	      setMotoboys((prev) => prev.filter((m) => m.id !== mb.id));
194	    } catch (err) {
195	      setMsg({ tipo: 'erro', texto: err.message });
196	    } finally {
197	      setRemovendo(null);
198	    }
199	  };
200	
201	  if (loading) return (
202	    <div className="min-h-screen flex items-center justify-center bg-[#F4F4F5] dark:bg-[#18181B]">
203	      <div className="w-8 h-8 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
204	    </div>
205	  );
206	
207	  return (
208	    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B]">
209	      <RestauranteHeader active="/restaurante/motoboys" title="Motoboys" subtitle="Entregadores afiliados ao seu estabelecimento" onRefresh={reload} />
210	
211	      <main className="max-w-2xl mx-auto px-4 py-6 space-y-5">
212	        {msg && (
213	          <div className={`text-sm rounded-xl px-4 py-3 ${
214	            msg.tipo === 'ok' ? 'bg-green-50 dark:bg-green-950/40 text-green-700 dark:text-green-400 border border-green-200 dark:border-green-800' : 'bg-red-50 dark:bg-red-950/40 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800'
215	          }`}>
216	            {msg.texto}
217	          </div>
218	        )}
219	
220	        {/* Abas */}
221	        <div className="flex gap-1 bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl p-1">
222	          {[
223	            { id: 'pendentes', label: 'Pendentes', count: solicitacoes.length },
224	            { id: 'aceitas', label: 'Aceitas', count: motoboys.length },
225	            { id: 'recusadas', label: 'Recusadas', count: recusadas.length },
226	          ].map((t) => (
227	            <button key={t.id} onClick={() => setAba(t.id)}
228	              className={`flex-1 flex items-center justify-center gap-1.5 py-2 text-sm font-bold rounded-lg transition-colors ${
229	                aba === t.id ? 'bg-[#FF441F] text-white shadow-sm' : 'text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]'
230	              }`}>
231	              {t.label}
232	              {t.count > 0 && (
233	                <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${
234	                  aba === t.id ? 'bg-white/20 text-white' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#71717A] dark:text-[#A1A1AA]'
235	                }`}>
236	                  {t.count}
237	                </span>
238	              )}
239	            </button>
240	          ))}
241	        </div>
242	
243	        {aba === 'pendentes' && (
244	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] divide-y divide-[#F4F4F5] dark:divide-[#3F3F46]">
245	            {solicitacoes.length === 0 ? (
246	              <p className="p-5 text-sm text-[#71717A] dark:text-[#A1A1AA] text-center">Nenhuma solicitação pendente</p>
247	            ) : solicitacoes.map((s) => (
248	              <button key={s.id} onClick={() => setFicha(s)}
249	                className="w-full flex items-center gap-3 p-4 hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46] transition-colors text-left">
250	                <div className="w-10 h-10 rounded-full overflow-hidden bg-[#F4F4F5] dark:bg-[#3F3F46] flex-shrink-0">
251	                  {s.motoboy.foto_perfil_url && !isPdfUrl(s.motoboy.foto_perfil_url)
252	                    ? <img src={s.motoboy.foto_perfil_url} alt={s.motoboy.name} className="w-full h-full object-cover" />
253	                    : <div className="w-full h-full flex items-center justify-center"><Icon name="User" size={16} className="text-[#A1A1AA]" /></div>}
254	                </div>
255	                <div className="flex-1 min-w-0">
256	                  <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5] truncate">{s.motoboy.name}</p>
257	                  <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{s.motoboy.phone}</p>
258	                </div>
259	                <Icon name="ChevronRight" size={16} className="text-[#A1A1AA] flex-shrink-0" />
260	              </button>
261	            ))}
262	          </div>
263	        )}
264	
265	        {aba === 'aceitas' && (
266	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] divide-y divide-[#F4F4F5] dark:divide-[#3F3F46]">
267	            {motoboys.length === 0 ? (
268	              <p className="p-5 text-sm text-[#71717A] dark:text-[#A1A1AA] text-center">
269	                Nenhum motoboy afiliado ainda. O entregador se cadastra pelo app e solicita atender aqui.
270	              </p>
271	            ) : motoboys.map((mb) => (
272	              <div key={mb.id} className="p-4 flex items-center gap-3">
273	                <div className="w-9 h-9 rounded-full overflow-hidden bg-[#FF441F]/10 flex-shrink-0">
274	                  {mb.foto_perfil_url && !isPdfUrl(mb.foto_perfil_url)
275	                    ? <img src={mb.foto_perfil_url} alt={mb.name} className="w-full h-full object-cover" />
276	                    : <div className="w-full h-full flex items-center justify-center"><Icon name="Bike" size={16} className="text-[#FF441F]" /></div>}
277	                </div>
278	                <div className="flex-1 min-w-0">
279	                  <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5]">{mb.name}</p>
280	                  {mb.phone && <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{mb.phone}</p>}
281	                  {mb.sessao_ativa && (
282	                    <span className="inline-block mt-1 text-[10px] px-2 py-0.5 rounded-full font-medium bg-amber-100 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400">
283	                      Logado em 1 dispositivo
284	                    </span>
285	                  )}
286	                </div>
287	                {mb.sessao_ativa && (
288	                  <button
289	                    onClick={() => handleForcarLogout(mb)}
290	                    disabled={forcandoLogout === mb.id}
291	                    className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400 hover:bg-amber-100 dark:hover:bg-amber-950/40 disabled:opacity-50 flex-shrink-0"
292	                  >
293	                    {forcandoLogout === mb.id ? '...' : 'Forçar logout'}
294	                  </button>
295	                )}
296	                <button
297	                  onClick={() => handleRemover(mb)}
298	                  disabled={removendo === mb.id}
299	                  className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-red-50 dark:bg-red-950/40 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-950/40 disabled:opacity-50 flex-shrink-0"
300	                >
301	                  {removendo === mb.id ? '...' : 'Remover'}
302	                </button>
303	              </div>
304	            ))}
305	          </div>
306	        )}
307	
308	        {aba === 'recusadas' && (
309	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] divide-y divide-[#F4F4F5] dark:divide-[#3F3F46]">
310	            {recusadas.length === 0 ? (
311	              <p className="p-5 text-sm text-[#71717A] dark:text-[#A1A1AA] text-center">Nenhuma solicitação recusada</p>
312	            ) : recusadas.map((s) => (
313	              <div key={s.id} className="p-4">
314	                <div className="flex items-center justify-between gap-3">
315	                  <div className="min-w-0">
316	                    <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5] truncate">{s.motoboy.name}</p>
317	                    <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{s.motoboy.phone}</p>
318	                  </div>
319	                  <div className="flex items-center gap-2 flex-shrink-0">
320	                    <p className="text-xs text-[#A1A1AA]">
321	                      {s.respondido_em && new Date(s.respondido_em).toLocaleDateString('pt-BR')}
322	                    </p>
323	                    <button
324	                      onClick={() => { setFicha(s); setFichaSomenteLeitura(true); }}
325	                      className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#E4E4E7] dark:hover:bg-[#3F3F46]"
326	                    >
327	                      Ver ficha
328	                    </button>
329	                    <button
330	                      onClick={() => handleRevisar(s.id)}
331	                      disabled={revisando === s.id}
332	                      className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 hover:bg-blue-100 dark:hover:bg-blue-950/40 disabled:opacity-50"
333	                    >
334	                      {revisando === s.id ? '...' : 'Revisão'}
335	                    </button>
336	                  </div>
337	                </div>
338	                {s.motivo_recusa && (
339	                  <p className="text-xs text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/40 rounded-lg px-3 py-2 mt-2">{s.motivo_recusa}</p>
340	                )}
341	              </div>
342	            ))}
343	          </div>
344	        )}
345	      </main>
346	
347	      {ficha && (
348	        <FichaModal
349	          solicitacao={ficha}
350	          onFechar={() => { setFicha(null); setFichaSomenteLeitura(false); }}
351	          onAceitar={handleAceitar}
352	          onRecusar={handleRecusar}
353	          processando={processando}
354	          somenteLeitura={fichaSomenteLeitura}
355	        />
356	      )}
357	    </div>
358	  );
359	};
360	
361	export default RestauranteMotoboys;
