1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { ComissaoService } from './comissao.service';
4	import { GeocodingService } from './geocoding.service';
5	import { EstoqueService } from '../estoque/estoque.service';
6	import { SalaoService } from '../salao/salao.service';
7	
8	const DOC_BUCKET = 'motoboy-documentos';
9	const SIGNED_URL_TTL = 60 * 10; // 10 min
10	
11	@Injectable()
12	export class MotoboyService {
13	  constructor(
14	    private supabase: SupabaseService,
15	    private comissao: ComissaoService,
16	    private geocoding: GeocodingService,
17	    private estoque: EstoqueService,
18	    private salaoService: SalaoService,
19	  ) {}
20	
21	  // Antes de ver/solicitar vaga em qualquer estabelecimento, a plataforma
22	  // (admin) precisa ter revisado e aprovado o cadastro do motoboy.
23	  private async exigirAprovacaoPlataforma(motoboyId: number) {
24	    const { data } = await this.supabase.client
25	      .from('motoboys')
26	      .select('status_plataforma')
27	      .eq('id', motoboyId)
28	      .maybeSingle();
29	    if (data?.status_plataforma !== 'aprovado') {
30	      throw new ForbiddenException('Seu cadastro ainda está em análise pela plataforma. Aguarde a aprovação pra ver os estabelecimentos.');
31	    }
32	  }
33	
34	  private async exigirAfiliacaoAceita(motoboyId: number, restaurantId: number) {
35	    const { data } = await this.supabase.client
36	      .from('motoboy_estabelecimentos')
37	      .select('id')
38	      .eq('motoboy_id', motoboyId)
39	      .eq('restaurant_id', restaurantId)
40	      .eq('status', 'aceito')
41	      .maybeSingle();
42	    if (!data) throw new ForbiddenException('Motoboy não está afiliado a este estabelecimento');
43	  }
44	
45	  // Estabelecimento que optou por entregar por conta própria não deve aparecer
46	  // pra motoboys pegarem pedido sozinhos — o dono ainda pode atribuir manualmente
47	  // como exceção (não passa por aqui).
48	  private async exigirUsaMotoboy(restaurantId: number) {
49	    const { data } = await this.supabase.client
50	      .from('restaurants')
51	      .select('usa_motoboy')
52	      .eq('id', restaurantId)
53	      .maybeSingle();
54	    if (data && data.usa_motoboy === false) {
55	      throw new ForbiddenException('Este estabelecimento faz entregas por conta própria');
56	    }
57	  }
58	
59	  private async signedUrl(path: string | null | undefined): Promise<string | null> {
60	    if (!path) return null;
61	    const { data } = await this.supabase.client.storage.from(DOC_BUCKET).createSignedUrl(path, SIGNED_URL_TTL);
62	    return data?.signedUrl ?? null;
63	  }
64	
65	  // ── Lado restaurante: gestão de afiliados ──────────────────────────
66	
67	  async listar(restaurantId: number) {
68	    const { data, error } = await this.supabase.client
69	      .from('motoboy_estabelecimentos')
70	      .select('motoboy:motoboys(id, name, phone, foto_perfil_url, active_session_id, session_expires_at)')
71	      .eq('restaurant_id', restaurantId)
72	      .eq('status', 'aceito');
73	    if (error) throw error;
74	
75	    const agora = Date.now();
76	    const motoboys = await Promise.all(
77	      (data ?? []).map(async (row: any) => {
78	        const { active_session_id, session_expires_at, ...resto } = row.motoboy ?? {};
79	        return {
80	          ...resto,
81	          foto_perfil_url: await this.signedUrl(resto.foto_perfil_url),
82	          sessao_ativa: !!active_session_id && !!session_expires_at && new Date(session_expires_at).getTime() > agora,
83	        };
84	      }),
85	    );
86	    return { motoboys };
87	  }
88	
89	  async listarSolicitacoes(restaurantId: number, status: 'pendente' | 'aceito' | 'recusado' = 'pendente') {
90	    // Pra pendente precisamos da ficha completa (docs via signed URL); pra histórico
91	    // (aceito/recusado) só o básico, evita gerar signed URL à toa por linha.
92	    const campos = status === 'pendente'
93	      ? 'motoboy:motoboys(id, name, phone, email, foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url)'
94	      : 'motoboy:motoboys(id, name, phone, email)';
95	
96	    const { data, error } = await this.supabase.client
97	      .from('motoboy_estabelecimentos')
98	      .select(`id, solicitado_em, respondido_em, motivo_recusa, ${campos}`)
99	      .eq('restaurant_id', restaurantId)
100	      .eq('status', status)
101	      .order(status === 'pendente' ? 'solicitado_em' : 'respondido_em', { ascending: status === 'pendente' });
102	    if (error) throw error;
103	
104	    if (status !== 'pendente') {
105	      return {
106	        solicitacoes: (data ?? []).map((row: any) => ({
107	          id: row.id,
108	          solicitado_em: row.solicitado_em,
109	          respondido_em: row.respondido_em,
110	          motivo_recusa: row.motivo_recusa,
111	          motoboy: row.motoboy,
112	        })),
113	      };
114	    }
115	
116	    const solicitacoes = await Promise.all(
117	      (data ?? []).map(async (row: any) => ({
118	        id: row.id,
119	        solicitado_em: row.solicitado_em,
120	        motoboy: {
121	          ...row.motoboy,
122	          foto_perfil_url: await this.signedUrl(row.motoboy?.foto_perfil_url),
123	          documento_frente_url: await this.signedUrl(row.motoboy?.documento_frente_url),
124	          documento_verso_url: await this.signedUrl(row.motoboy?.documento_verso_url),
125	          comprovante_endereco_url: await this.signedUrl(row.motoboy?.comprovante_endereco_url),
126	        },
127	      })),
128	    );
129	    return { solicitacoes };
130	  }
131	
132	  async contarSolicitacoesPendentes(restaurantId: number) {
133	    const { count, error } = await this.supabase.client
134	      .from('motoboy_estabelecimentos')
135	      .select('id', { count: 'exact', head: true })
136	      .eq('restaurant_id', restaurantId)
137	      .eq('status', 'pendente');
138	    if (error) throw error;
139	    return { count: count ?? 0 };
140	  }
141	
142	  async aceitarSolicitacao(id: number, restaurantId: number) {
143	    const { data, error } = await this.supabase.client
144	      .from('motoboy_estabelecimentos')
145	      .update({ status: 'aceito', respondido_em: new Date().toISOString(), updated_at: new Date().toISOString() })
146	      .eq('id', id)
147	      .eq('restaurant_id', restaurantId)
148	      .eq('status', 'pendente')
149	      .select()
150	      .maybeSingle();
151	    if (error) throw error;
152	    if (!data) throw new NotFoundException('Solicitação não encontrada ou já respondida');
153	    return data;
154	  }
155	
156	  async recusarSolicitacao(id: number, restaurantId: number, motivo?: string) {
157	    const { data, error } = await this.supabase.client
158	      .from('motoboy_estabelecimentos')
159	      .update({
160	        status: 'recusado',
161	        motivo_recusa: motivo ?? null,
162	        respondido_em: new Date().toISOString(),
163	        updated_at: new Date().toISOString(),
164	      })
165	      .eq('id', id)
166	      .eq('restaurant_id', restaurantId)
167	      .eq('status', 'pendente')
168	      .select()
169	      .maybeSingle();
170	    if (error) throw error;
171	    if (!data) throw new NotFoundException('Solicitação não encontrada ou já respondida');
172	    return data;
173	  }
174	
175	  // Restaurante muda de ideia sobre uma solicitação recusada — volta pra "pendente"
176	  // pra reavaliar (limpa motivo/data da recusa anterior).
177	  async revisarSolicitacao(id: number, restaurantId: number) {
178	    const { data, error } = await this.supabase.client
179	      .from('motoboy_estabelecimentos')
180	      .update({
181	        status: 'pendente',
182	        motivo_recusa: null,
183	        respondido_em: null,
184	        updated_at: new Date().toISOString(),
185	      })
186	      .eq('id', id)
187	      .eq('restaurant_id', restaurantId)
188	      .eq('status', 'recusado')
189	      .select()
190	      .maybeSingle();
191	    if (error) throw error;
192	    if (!data) throw new NotFoundException('Solicitação recusada não encontrada');
193	    return data;
194	  }
195	
196	  async removerAfiliacao(motoboyId: number, restaurantId: number) {
197	    const { data, error } = await this.supabase.client
198	      .from('motoboy_estabelecimentos')
199	      .update({ status: 'removido', updated_at: new Date().toISOString() })
200	      .eq('motoboy_id', motoboyId)
201	      .eq('restaurant_id', restaurantId)
202	      .eq('status', 'aceito')
203	      .select()
204	      .maybeSingle();
205	    if (error) throw error;
206	    if (!data) throw new NotFoundException('Afiliação não encontrada');
207	    return { ok: true };
208	  }
209	
210	  // Libera o motoboy pra logar em outro dispositivo, encerrando a sessão travada.
211	  async forcarLogout(motoboyId: number, restaurantId: number) {
212	    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);
213	    const { error } = await this.supabase.client
214	      .from('motoboys')
215	      .update({ active_session_id: null, session_expires_at: null })
216	      .eq('id', motoboyId);
217	    if (error) throw error;
218	    return { ok: true };
219	  }
220	
221	  async atribuir(pedidoId: number, restaurantId: number, motoboyId: number) {
222	    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);
223	
224	    const { error } = await this.supabase.client
225	      .from('orders')
226	      .update({ motoboy_id: motoboyId, status: 'out_for_delivery', updated_at: new Date().toISOString() })
227	      .eq('id', pedidoId)
228	      .eq('restaurant_id', restaurantId);
229	    if (error) throw error;
230	    return { ok: true, status: 'out_for_delivery' };
231	  }
232	
233	  // ── Lado motoboy: buscar/solicitar afiliação ───────────────────────
234	
235	  async buscarEstabelecimentos(motoboyId: number, busca?: string) {
236	    await this.exigirAprovacaoPlataforma(motoboyId);
237	
238	    let query = this.supabase.client
239	      .from('restaurants')
240	      .select('id, name, address, logo_url')
241	      .eq('bloqueado', false)
242	      .order('name')
243	      .limit(50);
244	    if (busca) query = query.ilike('name', `%${busca}%`);
245	    const { data: restaurantes, error } = await query;
246	    if (error) throw error;
247	
248	    const ids = (restaurantes ?? []).map((r) => r.id);
249	    const { data: afiliacoes } = ids.length
250	      ? await this.supabase.client
251	          .from('motoboy_estabelecimentos')
252	          .select('restaurant_id, status')
