377	  async confirmarEntrega(
378	    pedidoId: number,
379	    motoboyId: number,
380	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
381	  ) {
382	    const { data: pedido } = await this.supabase.client
383	      .from('orders')
384	      .select('id, status, restaurant_id, total, frete_cobrado, customer_id, payment_method')
385	      .eq('id', pedidoId)
386	      .eq('motoboy_id', motoboyId)
387	      .maybeSingle();
388	    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');
389	
390	    const updatePayload: Record<string, any> = { status: 'delivered', updated_at: new Date().toISOString() };
391	    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;
392	
393	    const { error } = await this.supabase.client
394	      .from('orders')
395	      .update(updatePayload)
396	      .eq('id', pedidoId);
397	    if (error) throw error;
398	
399	    // Registrar entrada(s) no caixa aberto
400	    if (entregaPagamento && pedido.restaurant_id) {
401	      const { data: caixa } = await this.supabase.client
402	        .from('caixas')
403	        .select('id, entradas')
404	        .eq('restaurant_id', pedido.restaurant_id)
405	        .eq('status', 'aberto')
406	        .maybeSingle();
407	
408	      if (caixa) {
409	        const entradas = (caixa.entradas ?? []) as any[];
410	        const novas: any[] = [];
411	        const agora = new Date().toISOString();
412	
413	        if ((entregaPagamento.dinheiro ?? 0) > 0) {
414	          novas.push({
415	            descricao: `Entrega pedido #${pedidoId} — dinheiro`,
416	            valor: entregaPagamento.dinheiro,
417	            meio: 'dinheiro',
418	            criado_em: agora,
419	          });
420	        }
421	        if ((entregaPagamento.pix ?? 0) > 0) {
422	          novas.push({
423	            descricao: `Entrega pedido #${pedidoId} — PIX`,
424	            valor: entregaPagamento.pix,
425	            meio: 'pix',
426	            criado_em: agora,
427	          });
428	        }
429	
430	        if (novas.length > 0) {
431	          await this.supabase.client
432	            .from('caixas')
433	            .update({ entradas: [...entradas, ...novas] })
434	            .eq('id', caixa.id);
435	        }
436	      }
437	    }
438	
439	    // Pedido já veio com "pagamento em dinheiro" escolhido no checkout (não é o motoboy
440	    // reportando o que cobrou na hora — isso é o `entregaPagamento` acima) — sem isso o
441	    // caixa físico nunca credita essa venda, só o fundo inicial (mesmo bug do salão).
442	    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash' && pedido.restaurant_id) {
443	      await this.salaoService.registrarEntradaCaixa(pedido.restaurant_id, `Venda delivery em dinheiro - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
444	    }
445	
446	    // Calcula e registra a comissão do motoboy (idempotente — UNIQUE(pedido_id))
447	    await this.comissao.registrarComissaoEntrega(pedido, motoboyId);
448	
449	    return { ok: true, pedido_id: pedidoId, status: 'delivered' };
450	  }
