453	  // Só permitido se não houver motoboy atribuído (evita marcar como entrega própria
454	  // um pedido que já está com um motoboy de verdade).
455	  async entregarProprio(
456	    pedidoId: number,
457	    restaurantId: number,
458	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
459	  ) {
460	    const { data: pedido } = await this.supabase.client
461	      .from('orders')
462	      .select('id, status, restaurant_id, motoboy_id, total, payment_method')
463	      .eq('id', pedidoId)
464	      .eq('restaurant_id', restaurantId)
465	      .maybeSingle();
466	    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
467	    if (pedido.motoboy_id) throw new BadRequestException('Pedido já está atribuído a um motoboy');
468	
469	    const updatePayload: Record<string, any> = {
470	      status: 'delivered',
471	      entrega_propria: true,
472	      updated_at: new Date().toISOString(),
473	    };
474	    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;
475	
476	    const { error } = await this.supabase.client.from('orders').update(updatePayload).eq('id', pedidoId);
477	    if (error) throw error;
478	
479	    if (entregaPagamento) {
480	      const { data: caixa } = await this.supabase.client
481	        .from('caixas')
482	        .select('id, entradas')
483	        .eq('restaurant_id', restaurantId)
484	        .eq('status', 'aberto')
485	        .maybeSingle();
486	
487	      if (caixa) {
488	        const entradas = (caixa.entradas ?? []) as any[];
489	        const novas: any[] = [];
490	        const agora = new Date().toISOString();
491	
492	        if ((entregaPagamento.dinheiro ?? 0) > 0) {
493	          novas.push({
494	            descricao: `Entrega própria pedido #${pedidoId} — dinheiro`,
495	            valor: entregaPagamento.dinheiro,
496	            meio: 'dinheiro',
497	            criado_em: agora,
498	          });
499	        }
500	        if ((entregaPagamento.pix ?? 0) > 0) {
501	          novas.push({
502	            descricao: `Entrega própria pedido #${pedidoId} — PIX`,
503	            valor: entregaPagamento.pix,
504	            meio: 'pix',
505	            criado_em: agora,
506	          });
507	        }
508	
509	        if (novas.length > 0) {
510	          await this.supabase.client.from('caixas').update({ entradas: [...entradas, ...novas] }).eq('id', caixa.id);
511	        }
512	      }
513	    }
514	
515	    // Idem confirmarEntrega: pedido pago em dinheiro no checkout, sem o dono reportar
516	    // via entregaPagamento — precisa creditar o caixa físico do mesmo jeito.
517	    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash') {
518	      await this.salaoService.registrarEntradaCaixa(restaurantId, `Venda delivery em dinheiro (entrega própria) - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
519	    }
520	
521	    return { ok: true, pedido_id: pedidoId, status: 'delivered', entrega_propria: true };
522	  }
