640	  async confirmarColeta(pedidoId: number, motoboyId: number, barcode: string) {
641	    const expected = String(pedidoId).padStart(8, '0');
642	    const scanned = barcode.replace(/\D/g, '').padStart(8, '0');
643	    if (scanned !== expected) {
644	      throw new BadRequestException('Código de barras não confere com este pedido');
645	    }
646	
647	    const { data: pedido } = await this.supabase.client
648	      .from('orders')
649	      .select('id, total, troco_para, payment_method, restaurant_id')
650	      .eq('id', pedidoId)
