661	
662	    const trocoValor = pedido.payment_method === 'cash' && pedido.troco_para > pedido.total
663	      ? Number(pedido.troco_para) - Number(pedido.total)
664	      : 0;
665	    if (trocoValor > 0) {
666	      const { data: caixa } = await this.supabase.client
667	        .from('caixas')
668	        .select('id, saidas')
669	        .eq('restaurant_id', pedido.restaurant_id)
670	        .eq('status', 'aberto')
671	        .maybeSingle();
672	      if (caixa) {
