697	    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');
698	
699	    const matches = base64.match(/^data:(image\/\w+);base64,(.+)$/);
700	    const mimeType = matches ? matches[1] : 'image/jpeg';
701	    const raw = matches ? matches[2] : base64;
702	    const buffer = Buffer.from(raw, 'base64');
703	    const ext = mimeType === 'image/png' ? 'png' : 'jpg';
704	    const path = `pedido-${pedidoId}-${Date.now()}.${ext}`;
705	
706	    const { error: uploadError } = await this.supabase.client.storage
707	      .from('comprovantes-pix')
