709	    if (uploadError) throw uploadError;
710	
711	    const { data: { publicUrl } } = this.supabase.client.storage
712	      .from('comprovantes-pix')
713	      .getPublicUrl(path);
714	
715	    await this.supabase.client
716	      .from('orders')
717	      .update({ comprovante_pix_url: publicUrl, updated_at: new Date().toISOString() })
718	      .eq('id', pedidoId);
