1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  getConfig, updateConfig, listarImpressoras, getMinhaEmpresa, updateEmpresa,
5	  atualizarLocalizacaoManual,
6	  listarComissoesGarcom, criarComissaoGarcom, atualizarComissaoGarcom, removerComissaoGarcom,
7	} from '../../services/restauranteService';
8	import { buscarCep } from '../../utils/viaCep';
9	import Icon from '../../components/AppIcon';
10	import { useModulosEmpresa } from '../../hooks/useModulosEmpresa';
11	import RestauranteHeader from '../../components/restaurante/RestauranteHeader';
12	import MapaLocalizacaoPicker from '../../components/MapaLocalizacaoPicker';
13	
14	// URL webhook gerada automaticamente — PagBank chama este endereço ao confirmar pagamento
15	const WEBHOOK_URL = `${window.location.origin}/api/pagamentos/webhook`;
16	
17	const PAGBANK_URL = 'https://pagseguro.uol.com.br';
18	
19	/* Guia passo a passo colapsável */
20	const Guia = () => {
21	  const [aberto, setAberto] = useState(false);
22	  const [copiado, setCopiado] = useState(false);
23	
24	  const copiarWebhook = () => {
25	    navigator.clipboard.writeText(WEBHOOK_URL).then(() => {
26	      setCopiado(true);
27	      setTimeout(() => setCopiado(false), 2000);
28	    });
29	  };
30	
31	  return (
32	    <div className="bg-blue-50 dark:bg-blue-950/40 border border-blue-100 dark:border-blue-800 rounded-xl overflow-hidden">
33	      <button
34	        type="button"
35	        onClick={() => setAberto((v) => !v)}
36	        className="w-full flex items-center justify-between px-5 py-4 text-left"
37	      >
38	        <div className="flex items-center gap-2">
39	          <Icon name="BookOpen" size={16} className="text-blue-600 dark:text-blue-400" />
40	          <span className="text-sm font-semibold text-blue-800 dark:text-blue-400">Como configurar o PagBank? (passo a passo)</span>
41	        </div>
42	        <Icon name={aberto ? 'ChevronUp' : 'ChevronDown'} size={16} className="text-blue-500 dark:text-blue-400 flex-shrink-0" />
43	      </button>
44	
45	      {aberto && (
46	        <div className="px-5 pb-5 space-y-4 border-t border-blue-100 dark:border-blue-800">
47	          <ol className="space-y-3 mt-4">
48	            <li className="flex gap-3">
49	              <span className="w-6 h-6 bg-blue-500 text-white rounded-full text-xs font-bold flex items-center justify-center flex-shrink-0 mt-0.5">1</span>
50	              <div>
51	                <p className="text-sm font-medium text-blue-900 dark:text-blue-400">Acesse o PagBank</p>
52	                <p className="text-xs text-blue-700 dark:text-blue-400 mt-0.5">
53	                  Crie uma conta ou faça login em{' '}
54	                  <a href={PAGBANK_URL} target="_blank" rel="noopener noreferrer"
55	                    className="underline font-semibold">pagseguro.uol.com.br</a>
56	                </p>
57	              </div>
58	            </li>
59	
60	            <li className="flex gap-3">
61	              <span className="w-6 h-6 bg-blue-500 text-white rounded-full text-xs font-bold flex items-center justify-center flex-shrink-0 mt-0.5">2</span>
62	              <div>
63	                <p className="text-sm font-medium text-blue-900 dark:text-blue-400">Obtenha o Token</p>
64	                <p className="text-xs text-blue-700 dark:text-blue-400 mt-0.5">
65	                  <strong>Minha Conta → Preferências → Integrações → Token de Segurança</strong><br />
66	                  Copie o token e cole no campo "Token PagBank" abaixo.
67	                </p>
68	              </div>
69	            </li>
70	
71	            <li className="flex gap-3">
72	              <span className="w-6 h-6 bg-blue-500 text-white rounded-full text-xs font-bold flex items-center justify-center flex-shrink-0 mt-0.5">3</span>
73	              <div>
74	                <p className="text-sm font-medium text-blue-900 dark:text-blue-400">Obtenha seu Account ID</p>
75	                <p className="text-xs text-blue-700 dark:text-blue-400 mt-0.5">
76	                  <strong>Minha Conta → Dados da Conta → Identificador da conta</strong><br />
77	                  Formato: <code className="bg-blue-100 dark:bg-blue-950/40 px-1 rounded">ACCT_XXXXXXXXXXXX</code>. Cole no campo "ID da conta" abaixo.
78	                </p>
79	              </div>
80	            </li>
81	
82	            <li className="flex gap-3">
83	              <span className="w-6 h-6 bg-blue-500 text-white rounded-full text-xs font-bold flex items-center justify-center flex-shrink-0 mt-0.5">4</span>
84	              <div>
85	                <p className="text-sm font-medium text-blue-900 dark:text-blue-400">Copie a URL Webhook (gerada automaticamente)</p>
86	                <p className="text-xs text-blue-700 dark:text-blue-400 mt-1">Cadastre esta URL no PagBank em <strong>Preferências → Notificações</strong>:</p>
87	                <div className="flex items-center gap-2 mt-1.5">
88	                  <code className="flex-1 bg-white dark:bg-[#27272A] border border-blue-200 dark:border-blue-800 rounded-lg px-2 py-1.5 text-xs text-blue-900 dark:text-blue-400 font-mono break-all">
89	                    {WEBHOOK_URL}
90	                  </code>
91	                  <button type="button" onClick={copiarWebhook}
92	                    className={`flex-shrink-0 px-2 py-1.5 text-xs rounded-lg font-medium transition-colors ${
93	                      copiado ? 'bg-green-500 text-white' : 'bg-blue-500 text-white hover:bg-blue-600'
94	                    }`}>
95	                    {copiado ? '✓' : 'Copiar'}
96	                  </button>
97	                </div>
98	              </div>
99	            </li>
100	
101	            <li className="flex gap-3">
102	              <span className="w-6 h-6 bg-green-500 text-white rounded-full text-xs font-bold flex items-center justify-center flex-shrink-0 mt-0.5">5</span>
103	              <div>
104	                <p className="text-sm font-medium text-blue-900 dark:text-blue-400">Salve as configurações abaixo</p>
105	                <p className="text-xs text-blue-700 dark:text-blue-400 mt-0.5">
106	                  A URL Webhook já foi preenchida automaticamente. Só precisa do token e account ID.
107	                </p>
108	              </div>
109	            </li>
110	          </ol>
111	        </div>
112	      )}
113	    </div>
114	  );
115	};
116	
117	// Endereço estruturado (Estado/Cidade/Bairro/CEP) do estabelecimento — alimenta o
118	// filtro geográfico da home pública. Separado do resto da tela (que é config de
119	// pagamento/motoboy) porque usa outro endpoint (minha-empresa, não config).
120	// Endereço fica guardado como uma string só (address) — não é uma coluna separada de
121	// número. Pra evitar dono esquecer o número (some casos geocodificavam impreciso por
122	// causa disso), o form aqui separa Logradouro/Número visualmente e concatena os dois
123	// antes de salvar; ao carregar, tenta separar de volta um "..., 123" no fim da string
124	// já salva (melhor esforço — endereço antigo sem número cai tudo em Logradouro mesmo).
125	const separarNumero = (address) => {
126	  const m = (address ?? '').match(/^(.*?),?\s*(\d+[a-zA-Z]?)\s*$/);
127	  return m ? { logradouro: m[1].trim(), numero: m[2] } : { logradouro: address ?? '', numero: '' };
128	};
129	
130	const EnderecoCard = ({ geocodeFalhou }) => {
131	  const [form, setForm] = useState({ logradouro: '', numero: '', cep: '', neighborhood: '', city: '', state: '' });
132	  const [loading, setLoading] = useState(true);
133	  const [salvando, setSalvando] = useState(false);
134	  const [sucesso, setSucesso] = useState(false);
135	  const [erro, setErro] = useState(null);
136	  const [buscandoCep, setBuscandoCep] = useState(false);
137	  const [localizacao, setLocalizacao] = useState({ lat: null, lng: null });
138	  const [ajustadoManualmente, setAjustadoManualmente] = useState(false);
139	  const [salvandoLocalizacao, setSalvandoLocalizacao] = useState(false);
140	  const [sucessoLocalizacao, setSucessoLocalizacao] = useState(false);
141	  const [erroLocalizacao, setErroLocalizacao] = useState(null);
142	
143	  const formatCEP = (v) => {
144	    const n = v.replace(/\D/g, '');
145	    return n.length <= 8 ? n.replace(/(\d{5})(\d{0,3})/, (_, a, b) => (b ? `${a}-${b}` : a)) : v;
146	  };
147	
148	  const handleCepChange = async (e) => {
149	    const formatted = formatCEP(e.target.value);
150	    setForm((f) => ({ ...f, cep: formatted }));
151	
152	    const digitos = formatted.replace(/\D/g, '');
153	    if (digitos.length !== 8) return;
154	    setBuscandoCep(true);
155	    const endereco = await buscarCep(digitos);
156	    setBuscandoCep(false);
157	    if (!endereco) return;
158	    setForm((f) => ({
159	      ...f,
160	      logradouro: endereco.logradouro || f.logradouro,
161	      neighborhood: endereco.bairro || f.neighborhood,
162	      city: endereco.cidade || f.city,
163	      state: endereco.estado || f.state,
164	    }));
165	  };
166	
167	  useEffect(() => {
168	    getMinhaEmpresa()
169	      .then((d) => {
170	        const e = d.empresa ?? {};
171	        const { logradouro, numero } = separarNumero(e.address);
172	        setForm({
173	          logradouro,
174	          numero,
175	          cep: e.cep ?? '',
176	          neighborhood: e.neighborhood ?? '',
177	          city: e.city ?? '',
178	          state: e.state ?? '',
179	        });
180	        setLocalizacao({ lat: e.lat ?? null, lng: e.lng ?? null });
181	        setAjustadoManualmente(!!e.lat_ajustado_manualmente);
182	      })
183	      .catch((e) => setErro(e.message))
184	      .finally(() => setLoading(false));
185	  }, []);
186	
187	  const salvarLocalizacao = async () => {
188	    if (localizacao.lat == null || localizacao.lng == null) return;
189	    setSalvandoLocalizacao(true);
190	    setErroLocalizacao(null);
191	    setSucessoLocalizacao(false);
192	    try {
193	      await atualizarLocalizacaoManual(localizacao.lat, localizacao.lng);
194	      setAjustadoManualmente(true);
195	      setSucessoLocalizacao(true);
196	      setTimeout(() => setSucessoLocalizacao(false), 2500);
197	    } catch (err) {
198	      setErroLocalizacao(err.message);
199	    } finally {
200	      setSalvandoLocalizacao(false);
201	    }
202	  };
203	
204	  const salvar = async (e) => {
205	    e.preventDefault();
206	    if (!form.logradouro.trim() || !form.numero.trim()) {
207	      setErro('Informe logradouro e número.');
208	      return;
209	    }
210	    setSalvando(true);
211	    setErro(null);
212	    setSucesso(false);
213	    try {
214	      await updateEmpresa({
215	        address: `${form.logradouro.trim()}, ${form.numero.trim()}`,
216	        cep: form.cep.trim(),
217	        neighborhood: form.neighborhood.trim(),
218	        city: form.city.trim(),
219	        state: form.state.trim(),
220	      });
221	      setSucesso(true);
222	      setTimeout(() => setSucesso(false), 2500);
223	    } catch (err) {
224	      setErro(err.message);
225	    } finally {
226	      setSalvando(false);
227	    }
228	  };
229	
230	  return (
231	    <div className="bg-white dark:bg-[#27272A] rounded-xl border p-6">
232	      <h2 className="font-semibold text-[#18181B] dark:text-[#F4F4F5] mb-1">Endereço do estabelecimento</h2>
233	      <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mb-4">Usado pro filtro de Estado/Cidade/Bairro/CEP e "restaurantes perto de mim" na home.</p>
234	
235	      {geocodeFalhou && (
236	        <div className="mb-4 bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 rounded-lg px-3 py-2 text-xs text-amber-700 dark:text-amber-400">
237	          ⚠️ Não conseguimos localizar esse endereço no mapa — confira se está completo e correto.
238	        </div>
239	      )}
240	
241	      {loading ? (
242	        <div className="flex justify-center py-6">
243	          <div className="w-6 h-6 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
244	        </div>
245	      ) : (
246	        <form onSubmit={salvar} className="space-y-3">
247	          <div className="grid grid-cols-3 gap-3">
248	            <div className="col-span-2">
249	              <label className="text-xs font-medium text-[#71717A] dark:text-[#A1A1AA]">Logradouro (rua/av.)</label>
250	              <input value={form.logradouro} onChange={(e) => setForm((f) => ({ ...f, logradouro: e.target.value }))}
251	                placeholder="Rua Exemplo"
252	                className="w-full mt-1 border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#FF441F]" />
253	            </div>
