2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	@Injectable()
5	export class UsuariosService {
6	  constructor(private supabase: SupabaseService) {}
7	
8	  // Fonte única da regra "vínculo restaurants.user_id <-> user_profiles.role".
9	  // Idempotente: pode ser chamado com o mesmo novoUserId que já está no
10	  // restaurante (caso do /finalizar, que não troca dono, só garante a elevação).
11	  async sincronizarVinculoDono(restaurantId: number, novoUserId: string | null): Promise<void> {
12	    const { data: restaurant, error } = await this.supabase.client
13	      .from('restaurants')
14	      .select('user_id')
15	      .eq('id', restaurantId)
16	      .single();
17	    if (error) throw error;
18	
19	    const donoAnteriorId: string | null = restaurant.user_id;
20	
21	    if (donoAnteriorId !== novoUserId) {
22	      const { error: eUpd } = await this.supabase.client
23	        .from('restaurants')
24	        .update({ user_id: novoUserId, updated_at: new Date().toISOString() })
25	        .eq('id', restaurantId);
26	      if (eUpd) throw eUpd;
27	    }
28	
29	    if (novoUserId) await this.elevarSeNecessario(novoUserId);
30	    if (donoAnteriorId && donoAnteriorId !== novoUserId) await this.rebaixarSeOrfao(donoAnteriorId);
31	  }
32	
33	  private async elevarSeNecessario(userId: string): Promise<void> {
34	    const { data: perfil, error } = await this.supabase.client
35	      .from('user_profiles')
36	      .select('role')
37	      .eq('id', userId)
38	      .maybeSingle();
39	    if (error) throw error;
40	    if (!perfil || perfil.role === 'admin' || perfil.role === 'restaurant_owner') return;
41	
42	    const { error: eUpd } = await this.supabase.client
43	      .from('user_profiles')
44	      .update({ role: 'restaurant_owner', updated_at: new Date().toISOString() })
45	      .eq('id', userId);
46	    if (eUpd) throw eUpd;
47	  }
48	
49	  private async rebaixarSeOrfao(userId: string): Promise<void> {
50	    const { data: perfil } = await this.supabase.client
51	      .from('user_profiles')
52	      .select('role')
53	      .eq('id', userId)
54	      .maybeSingle();
55	    if (perfil?.role !== 'restaurant_owner') return;
56	
57	    const { data: outraLoja } = await this.supabase.client
58	      .from('restaurants')
59	      .select('id')
60	      .eq('user_id', userId)
61	      .maybeSingle();
62	    if (outraLoja) return;
63	
64	    await this.supabase.client
65	      .from('user_profiles')
66	      .update({ role: 'customer', updated_at: new Date().toISOString() })
67	      .eq('id', userId);
68	  }
69	
70	  async listar(params: { busca?: string; role?: string; page: number; limit: number }) {
71	    let query = this.supabase.client
72	      .from('user_profiles')
73	      .select('id, name, email, role, must_change_password, created_at', { count: 'exact' })
74	      .order('created_at', { ascending: false });
75	
76	    if (params.role) query = query.eq('role', params.role);
77	    if (params.busca) query = query.or(`name.ilike.%${params.busca}%,email.ilike.%${params.busca}%`);
78	
79	    const from = (params.page - 1) * params.limit;
80	    query = query.range(from, from + params.limit - 1);
81	
82	    const { data: usuarios, error, count } = await query;
83	    if (error) throw error;
84	
85	    const ids = (usuarios ?? []).map((u) => u.id);
86	    const { data: restaurantes } = ids.length
87	      ? await this.supabase.client.from('restaurants').select('id, name, slug, user_id').in('user_id', ids)
88	      : { data: [] as any[] };
89	
90	    const porUserId = new Map((restaurantes ?? []).map((r) => [r.user_id, r]));
91	    return {
92	      usuarios: (usuarios ?? []).map((u) => ({ ...u, restaurante: porUserId.get(u.id) ?? null })),
93	      total: count ?? 0,
94	    };
